const LIMITE_REVISION = 1000000;
const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
class LineaFactura {
  #descripcion; #cantidad; #precioUnitario;
  constructor(d) { this.#descripcion = String(d.descripcion ?? '').trim(); this.#cantidad = Number(d.cantidad); this.#precioUnitario = Number(d.precioUnitario); }
  get descripcion() { return this.#descripcion; } get cantidad() { return this.#cantidad; } get precioUnitario() { return this.#precioUnitario; }
  subtotal() { return redondear(this.#cantidad * this.#precioUnitario); }
}
class Factura {
  #lineas;
  constructor(d) { if (new.target === Factura) throw new Error('Factura es una clase base abstracta.'); this.id=d.id; this.tipo=d.tipo; this.proveedor=d.proveedor; this.cedulaJuridica=d.cedulaJuridica; this.fecha=d.fecha; this.moneda=String(d.moneda || 'CRC').toUpperCase(); this.tipoCambio=d.tipoCambio == null ? null : Number(d.tipoCambio); this.#lineas=(Array.isArray(d.lineas)?d.lineas:[]).map(x=>new LineaFactura(x)); }
  get lineas() { return this.#lineas.map(x=>({descripcion:x.descripcion,cantidad:x.cantidad,precioUnitario:x.precioUnitario})); }
  subtotal() { return redondear(this.#lineas.reduce((s,x)=>s+x.subtotal(),0)); }
  calcularImpuesto() { throw new Error('Subclase debe implementar calcularImpuesto().'); }
