    switch(String(d.tipo || '').toLowerCase()) {
      case 'nacional': return new FacturaNacional(d);
      case 'exenta': return new FacturaExenta(d);
      case 'extranjera': return new FacturaExtranjera(d);
      default: throw new Error(`Tipo desconocido: ${d.tipo || '(vacío)'}`);
    }
  }
}
class ValidadorFactura {
  validar(f) {
    const errores=[];
    if(!f.id || !f.proveedor || !f.cedulaJuridica) errores.push('Faltan datos obligatorios.');
    const cedula=String(f.cedulaJuridica||'').replace(/\D/g,'');
    if(cedula.length!==10 || cedula[0]!=='3') errores.push('Cédula jurídica inválida.');
    const hoy=new Date().toISOString().slice(0,10);
    const fechaOk=/^\d{4}-\d{2}-\d{2}$/.test(String(f.fecha||'')) && !Number.isNaN(Date.parse(`${f.fecha}T00:00:00Z`));
    if(!fechaOk) errores.push('Fecha inválida.'); else if(f.fecha>hoy) errores.push('Fecha futura.');
    if(!f.lineas.length || f.lineas.some(x=>!x.descripcion || !Number.isFinite(x.cantidad) || x.cantidad<=0 || !Number.isFinite(x.precioUnitario) || x.precioUnitario<0)) errores.push('Líneas de factura inválidas.');
    if(f.tipo==='extranjera') { if(!f.moneda || f.moneda==='CRC' || !Number.isFinite(f.tipoCambio) || f.tipoCambio<=0) errores.push('Moneda o tipo de cambio inválido.'); }
    else if(f.moneda!=='CRC') errores.push('La factura doméstica debe estar en CRC.');
    return {valida:errores.length===0,errores};
  }
}
